const cleanJson = (text: string) => {
  if (!text) return "{}";
  let cleaned = text.replace(/<think>[\s\S]*?<\/think>/g, '');
  cleaned = cleaned.replace(/```json\s*([\s\S]*?)\s*```/g, '$1');
  cleaned = cleaned.replace(/```\s*([\s\S]*?)\s*```/g, '$1');

  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  const firstBracket = cleaned.indexOf('[');
  const lastBracket = cleaned.lastIndexOf(']');

  let start = -1;
  let end = -1;

  if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
      start = firstBrace;
      end = lastBrace;
  } else if (firstBracket !== -1) {
      start = firstBracket;
      end = lastBracket;
  }

  if (start !== -1 && end !== -1) {
    cleaned = cleaned.substring(start, end + 1);
  }

  return cleaned.trim();
};

const parseJsonSafely = (text: string) => {
  try {
    return JSON.parse(text);
  } catch (e) {
    console.warn("JSON Parse Failed, returning raw text as aiExplanation.");
    return { aiExplanation: text };
  }
};

const callWithRetry = async <T>(fn: (ai: GoogleGenAI) => Promise<T>, retries = 3): Promise<T> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    return await fn(ai);
  } catch (error: any) {
    const errorMsg = error?.message || "";
    const isQuotaExceeded = errorMsg.includes('429') || errorMsg.includes('RESOURCE_EXHAUSTED') || error?.status === 429;

    if (retries > 0 && isQuotaExceeded) {
      console.warn(`[Gemini API] Quota reached. Retrying in 3s... (${retries} attempts left)`);
      await new Promise(resolve => setTimeout(resolve, 3000));
      return callWithRetry(fn, retries - 1);
    }

    if (isQuotaExceeded) {
      throw new Error("Maaf, kuota harian habis. Mohon coba lagi nanti.");
    }

    throw error;
  }
};

export const translateText = async (text: string): Promise<any> => {
  const cached = await fetchGlobalCache(text, 'translation');
  if (cached) return cached;

  const result = await callWithRetry(async (ai) => {
    const response = await ai.models.generateContent({
      model: GEMINI_MODEL,
      contents: text,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        thinkingConfig: { thinkingBudget: 1024 }, 
        responseMimeType: "application/json"
      }
    });
    if (response.text === undefined) throw new Error("Gagal mendapatkan respon dari AI.");
    return parseJsonSafely(cleanJson(response.text));
  });

  await saveGlobalCache(text, result, 'translation', GEMINI_MODEL);
  return result;
};

