    try {
        const publicData = await fetchPublicBook(searchName);
        if (publicData) return { ...publicData, sourceType: 'PUBLIC_LIBRARY' };
    } catch (e) {}

    // 2. Cek Cache AI
    const cacheKey = `book_detail:${searchName}`;
    const cached = await fetchGlobalCache(cacheKey, 'book_detail');
    if (cached) return { ...cached, sourceType: 'AI_CACHE' };

    // 3. Generate AI
    const prompt = `
    Berikan informasi detail dan SANGAT LENGKAP untuk kitab: "${searchName}" ${authorName ? `karya ${authorName}` : ''}.

    Output JSON (Wajib):
    {
        "name": "${searchName}",
        "desc": "Deskripsi singkat (1 kalimat)",
        "author": "Nama Lengkap Pengarang & Gelar",
        "year": "Tahun/Abad Lahir/Wafat (Hijriyah & Masehi)",
        "category": "Kategori Utama (pilih satu: Tafsir, Hadits, Fiqih, Aqidah, Tasawuf, Nahwu, Sejarah, Lainnya)",
        "longDesc": "Deskripsi mendalam tentang isi kitab, metode penulisan, keistimewaan, dan kedudukannya dalam mazhab/ilmu terkait (minimal 3 paragraf).",
        "chapters": [
        "Muqaddimah",
        "Bab 1: [Judul Bab]",
        "Bab 2: [Judul Bab]",
        ...
        "Khatimah"
        ] 
    }
    `;

    const detail = await generateJson(prompt, "Anda adalah ahli bedah kitab kuning dan pustakawan Islam.");

    // Save to Cache & Public Library
    await saveGlobalCache(cacheKey, detail, 'book_detail', GEMINI_MODEL);
    savePublicBook(detail, GEMINI_MODEL).catch(err => console.error("Auto-save public book failed", err));

    return { ...detail, sourceType: 'AI_FRESH' };
};

