export const generateSpeech = async (text: string, isArabic: boolean): Promise<string> => {
  const cacheType = isArabic ? 'tts_ar' : 'tts_id';
  const cached = await fetchGlobalCache(text, cacheType);
  if (cached && cached.audioUrl) return cached.audioUrl;

  const audioBase64 = await callWithRetry(async (ai) => {
    const voiceName = isArabic ? 'Kore' : 'Puck';
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName }
          }
        }
      }
    });

    const data = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!data) throw new Error("Gagal menghasilkan suara AI.");
    return data;
  });

  const publicUrl = await uploadAudioToStorage(audioBase64, text, cacheType);
  if (publicUrl) {
    await saveGlobalCache(text, { audioUrl: publicUrl }, cacheType, "gemini-2.5-flash-preview-tts");
    return publicUrl;
  }
  return ""; 
};

export const generateJson = async (prompt: string, systemInstruction?: string, skipCacheRead: boolean = false): Promise<any> => {
  if (!skipCacheRead) {
    const cached = await fetchGlobalCache(prompt, 'json_gen');
    if (cached) return cached;
  }

  const result = await callWithRetry(async (ai) => {
    const response = await ai.models.generateContent({
      model: GEMINI_MODEL,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction || "You are a helpful assistant. Output strictly JSON.",
        responseMimeType: "application/json"
      }
    });
    if (response.text === undefined) throw new Error("Gagal mendapatkan respon dari AI.");
    return parseJsonSafely(cleanJson(response.text));
  });

  await saveGlobalCache(prompt, result, 'json_gen', GEMINI_MODEL);
  return result;
};

