  const uniqueKey = `${topic}:${query.trim().toLowerCase()}`;
  const cached = await fetchGlobalCache(uniqueKey, 'religious_query');
  if (cached && cached.text) return cached.text; 

  const resultText = await callWithRetry(async (ai) => {
    const response = await ai.models.generateContent({
      model: GEMINI_MODEL,
      contents: query,
      config: {
        systemInstruction: `You are an expert Islamic scholar in ${topic}. Provide accurate, respectful answers based on Quran, Hadith, and Kitab Kuning (Aswaja). Language: Indonesian.`,
        thinkingConfig: { thinkingBudget: 512 }
      }
    });
    return response.text || "Maaf, tidak ada jawaban dari sistem.";
  });

  await saveGlobalCache(uniqueKey, { text: resultText }, 'religious_query', GEMINI_MODEL);
  return resultText;
};

