export const generateNewsAI = async (sourceOrTopic: string): Promise<any> => {
  const prompt = `
    Anda adalah jurnalis senior khusus dunia Islam dan Pesantren.
    Buatlah berita mendalam dan informatif berdasarkan input berikut: "${sourceOrTopic}".
    Jika input berupa link, ringkas isinya menjadi berita yang menarik. Jika topik, cari informasi terbaru (grounding).

    Output JSON (Wajib):
    {
      "title": "Judul Berita yang Menarik & Klik-able",
      "excerpt": "Ringkasan berita dalam 1-2 kalimat (Lead).",
      "content": "Isi berita lengkap minimal 5 paragraf. Gunakan gaya bahasa jurnalistik santun.",
      "category": "Kategori (Warta, Pesantren, Hikmah, Tekno-Islam, atau Internasional)",
      "grounding_source": "Link referensi utama jika tersedia"
    }
  `;

  const result = await callWithRetry(async (ai) => {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: "Anda adalah redaktur berita Islami yang ahli. Gunakan Google Search untuk akurasi data.",
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json"
      }
    });

    if (response.text === undefined) throw new Error("Gagal mendapatkan respon berita dari AI.");
    const parsed = parseJsonSafely(cleanJson(response.text));

    // Extract grounding URLs if search was used
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (groundingChunks && Array.isArray(groundingChunks)) {
      const urls = groundingChunks
        .map(chunk => chunk.web?.uri)
        .filter(uri => !!uri);
      if (urls.length > 0 && !parsed.grounding_source) {
        parsed.grounding_source = urls[0];
      }
    }

    return parsed;
  });

  return result;
};

